package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AcrValuesSupportedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property acr values supported of tenant config ")
  void test_acr_values_supported_v_o_builder() {
    Assertions.assertFalse(AcrValuesSupportedVO.nullValue().getAcrValuesSupported().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AcrValuesSupportedVO.tryFrom(null).getAcrValuesSupported().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        AcrValuesSupportedVO.from("one").getAcrValuesSupported().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AcrValuesSupportedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AcrValuesSupportedVO.from("one").toString());
  }
}
